// SPDX-License-Identifier: AGPL-3.0-or-later
// Room: Wing kitchen and scullery. Inner air box [5,6,23,10,12,29]; door x6 z22 (lobby), back door x11 z27, kitchen
// window x11 z24..25. Focal piece: the brick range on the south wall (x7..8 z29), in line with the lobby door.
// Layout (floor y6, tops y7), drawn as text with layers(): origin [5,6,23], rows along +x (x5..10), successive rows
// along +z (z23..29). Pantry barrels on the west wall, scullery sink and worktop under the window on the east wall,
// a worktable with two chairs in the middle. Lanterns hang from the y13 floor, the range's firebox lights the rest.
import { layers, B } from "/Volumes/ext1/swe/repos/minecraft-design/tools/src/build.mjs";
import { hangLantern } from "./../vocab/h3.mjs";

const legend6 = {
  b: "barrel",                                             // pantry barrels (west wall)
  W: ["water_cauldron", { level: "3" }],                   // scullery sink
  k: "spruce_planks",                                      // worktop base (east wall, under the window)
  f: "spruce_fence",                                       // worktable legs
  c: ["spruce_stairs", { facing: "north", half: "bottom" }], // chair north of the table (back north)
  C: ["spruce_stairs", { facing: "south", half: "bottom" }], // chair south of the table (back south)
  F: ["furnace", { facing: "north", lit: "true" }],        // range: furnace
  S: ["smoker", { facing: "north", lit: "true" }],         // range: smoker
};

const legend7 = {
  b: "barrel",                                             // stacked pantry barrel
  T: ["spruce_slab", { type: "bottom" }],                  // worktop and table top
  M: "bricks",                                             // range breast above the firebox
};

// y6 (floor furniture): x5..10 by z23..29; '.' is free floor (lanes: door cells x6 z23, x10 z27 stay clear)
const y6 = [
  "b.....W",  // z23 (lobby door first cell is x6 z23, kept clear)
  "b.c..kk",  // z24 under the kitchen window x11 z24..25
  ".ffk..k",  // z25 hmm placeholder, replaced below
];

export function build(g) {
  const origin = [5, 6, 23];
  const floor = [
    ["b.W..k", "b.c..k", ".ff...", "..C...", "......", "b.....", "bFS..."],
  ];
  void floor;
  // y6 rows, z23..z29, columns x5..x10
  const rows6 = [
    "b....W", // z23
    "b.c..k", // z24
    ".ff..k", // z25
    "..C...", // z26
    "......", // z27 (back door x11 z27: its first cell x10 z27 stays clear)
    "b.....", // z28
    "bFS...", // z29 range at x7..8 against the south wall
  ];
  // y7 rows: worktop slabs, the range breast, a stacked barrel
  const rows7 = [
    "b.....", // z23
    "......", // z24
    "..TT.T", // z25 table top over x7..8, worktop slab at x10
    "......", // z26
    "......", // z27
    "......", // z28
    ".MM...", // z29 breast over the range
  ];
  // the worktop slabs sit at x10 z24..25 as well
  rows7[1] = ".....T";
  rows7[2] = "..TT.T";
  layers(g, origin, legend6, [rows6]);
  layers(g, origin, legend7, [rows7]);
  // the worktop under the kitchen window is a counter: slab top at x10 z24, z25 (rows above)
  // hanging lanterns from the y13 floor: one over the table, one over the range side of the room
  hangLantern(g, 7, 12, 25);
  hangLantern(g, 9, 12, 27);
  return g;
}

